class SQLQueryBuilder:

    @staticmethod
    def select(table, columns='*', where=None):
        if not isinstance(columns, str):
            columns_str = ', '.join(columns)
        else:
            columns_str = columns

        sql = f"SELECT {columns_str} FROM {table}"

        if where:
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql

    @staticmethod
    def insert(table, data):
        columns = ', '.join(data.keys())
        escaped_values = ', '.join(f"'{value.replace("'", "''")}'" for value in data.values())
        sql = f"INSERT INTO {table} ({columns}) VALUES ({escaped_values})"
        return sql

    @staticmethod
    def delete(table, where=None):
        sql = f"DELETE FROM {table}"

        if where:
            conditions = []
            for key, value in where.items():
                escaped_value = value.replace("'", "''")
                conditions.append(f"{key}='{escaped_value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql

    @staticmethod
    def update(table, data, where=None):
        sql = f"UPDATE {table} SET "

        set_pairs = []
        for key, value in data.items():
            string_value = str(value)
            escaped_value = string_value.replace("'", "''")
            set_pairs.append(f"{key}='{escaped_value}'")
        sql += ', '.join(set_pairs)

        if where:
            conditions = []
            for key, value in where.items():
                string_value = str(value)
                escaped_value = string_value.replace("'", "''")
                conditions.append(f"{key}='{escaped_value}'")
            sql += f" WHERE {' AND '.join(conditions)}"

        return sql
